def solve_n_queens(n):
    solutions = []
    rows = []
    def conflicts(row, col):
        for other_row, other_col in enumerate(rows):
            if other_col == col or abs(other_row - row) == abs(other_col - col):
                return True
        return False
    def place(row):
        if row == n:
            solutions.append(["." * c + "Q" + "." * (n - c - 1) for c in rows])
            return
        for col in range(n):
            if not conflicts(row, col):
                rows.append(col)
                place(row + 1)
                rows.pop()
    place(0)
    return sorted(solutions)
